            exist[v] = 1;
            nums.push_back(v);
        }
    }

    vector<int> vis(maxA + 1, 0);
    queue<int> q;

    // 第一次取模得到初始状态
    for (int a : nums) {
        if (a <= x) {
            int r = x % a;
            if (!vis[r]) {
                vis[r] = 1;
                q.push(r);
            }
        }
    }

    // BFS 枚举所有可达状态
    while (!q.empty()) {
        int v = q.front();
        q.pop();

        for (int a : nums) {
            // 只有 a <= v 时，取模才会改变当前值
            if (a <= v) {
